// Sample floor plans for tests only. src/ holds no plan template (blank is
// the only one): a real plan is generated by the model and checked by code.
// These are the op envelopes the old built-in samples produced, so the plan
// engine, edits and transport tests keep the same geometry (the two
// bedrooms' shared wall is `w3`).
import { expandPlanDocument } from '../../src/plan/ai';

/** A two-bedroom flat (8 m × 6 m) as a plan document, the shape the model writes. */
export const TWO_BEDROOM_DOC = {
  unit: 'mm',
  rooms: [
    { name: 'Bedroom 1', x: 0, y: 3000, w: 4000, h: 3000 },
    { name: 'Bedroom 2', x: 4000, y: 3000, w: 4000, h: 3000 },
    { name: 'Living room', x: 0, y: 0, w: 4000, h: 3000 },
    { name: 'Kitchen', x: 4000, y: 0, w: 2000, h: 3000 },
    { name: 'Bathroom', x: 6000, y: 0, w: 2000, h: 3000 },
  ],
  doors: [
    { room: 'Living room', side: 's', width: 900 },
    { room: 'Bedroom 1', side: 's', width: 800 },
    { room: 'Bedroom 2', side: 's', width: 800 },
    { room: 'Kitchen', side: 'w', width: 800 },
    { room: 'Bathroom', side: 'w', width: 700 },
  ],
  windows: [
    { room: 'Bedroom 1', side: 'n', width: 1200 },
    { room: 'Bedroom 2', side: 'n', width: 1200 },
    { room: 'Living room', side: 'w', width: 1000 },
    { room: 'Kitchen', side: 's', width: 1000 },
    { room: 'Bathroom', side: 'e', width: 600 },
  ],
};

export function twoBedroomOps(): Record<string, unknown>[] {
  return expandPlanDocument(TWO_BEDROOM_DOC) as unknown as Record<string, unknown>[];
}

/** A single 4 m × 3 m room, dimensioned on its left wall and selected. */
export function oneRoomOps(): Record<string, unknown>[] {
  return [
    { op: 'add_room', nums: { x: 0, y: 0, w: 4, h: 3 }, unit: 'm', name: 'Room' },
    { op: 'add_dim', target: 'w5' },
    { op: 'select', target: 'w5' },
  ];
}

/** One 6 m × 4 m room with a door and a window on the front wall. */
export function studioOps(): Record<string, unknown>[] {
  return [
    { op: 'add_room', nums: { x: 0, y: 0, w: 6, h: 4 }, unit: 'm', name: 'Studio' },
    { op: 'add_door', target: 'w2', nums: { offset: 0.5, width: 0.9 }, unit: 'm' },
    { op: 'add_window', target: 'w4', nums: { width: 1.5 }, unit: 'm' },
    { op: 'add_dim', target: 'w2' },
    { op: 'select', target: 'w2' },
  ];
}
